{
  "name": "@guyghost/swarm-dao-opencode-adapter",
  "version": "0.6.3",
  "description": "Swarm DAO governance adapter for OpenCode — multi-agent deliberation, quality gates, and structured decision-making",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "sideEffects": false,
  "files": [
    "dist",
    "README.md"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "test": "bun test",
    "lint": "biome check .",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "dependencies": {
    "@guyghost/swarm-dao-core": "^2.0.0",
    "@guyghost/swarm-dao-graph": "^0.4.1",
    "@guyghost/swarm-dao-improvement": "^0.6.9",
    "@guyghost/swarm-dao-product": "^0.3.8"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.19"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@types/bun": "1.3.14"
  },
  "keywords": [
    "swarm-dao",
    "opencode",
    "opencode-plugin",
    "dao",
    "governance",
    "multi-agent",
    "deliberation",
    "ai-agents",
    "quality-gates"
  ],
  "author": "guyghost",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/guyghost/swarm-dao.git",
    "directory": "packages/opencode-adapter"
  },
  "bugs": {
    "url": "https://github.com/guyghost/swarm-dao/issues"
  },
  "homepage": "https://github.com/guyghost/swarm-dao#readme",
  "publishConfig": {
    "access": "public"
  }
}
